package Client;

public enum Command {
	Help("List all available commands", "[CommandName]"),

	AddFlight("Add a new flight number", "<FlightNumber>,<NumberOfSeats>,<PricePerSeat>"),
	AddCars("Add a new car location", "<Location>,<NumberOfCar>,<Price>"),
	AddRooms("Add a new room location", "<Location>,<NumberOfRoom>,<Price>"),
	AddCustomer("Generate a new customer id", ""),
	AddCustomerID("Create a new customer with the id", "<CustomerID>"),

	DeleteFlight("Delete a flight number", "<FlightNumber>"),
	DeleteCars("Delete all cars at a location", "<Location>"),
	DeleteRooms("Delete all rooms at a location", "<Location>"),
	DeleteCustomer("Delete a customer (and return all reservations)", "<CustomerID>"),

	QueryFlight("Query the number of available seats on a flight number", "<FlightNumber>"),
	QueryCars("Query the number of available cars at a location", "<Location>"),
	QueryRooms("Query the number of available rooms at a location", "<Location>"),
	QueryCustomer("Query a customer's bill", "<CustomerID>"),

	QueryFlightPrice("Query the price per seat on a flight number", "<FlightNumber>"),
	QueryCarsPrice("Query the price per car at a location", "<Location>"),
	QueryRoomsPrice("Query the price per room at a location", "<Location>"),

	ReserveFlight("Reserve a flight number for a customer", "<CustomerID>,<FlightNumber>"),
	ReserveCar("Reserve a car for a customer at a location", "<CustomerID>,<Location>"),
	ReserveRoom("Reserve a room for a customer at a location", "<CustomerID>,<Location>"),

	Bundle("Book N flight numbers, and optionally a room and/or car at a location", "<CustomerID>,<FlightNumber1>...<FlightNumberN>,<Location>,<Car-Y/N>,<Room-Y/N>"),

	Quit("Exit the client application", "");

	String m_description;
	String m_args;

	Command(String p_description, String p_args)
	{
		m_description = p_description;
		m_args = p_args;
	}

	public static Command fromString(String string)
	{
		for (Command cmd : Command.values())
		{
			if (cmd.name().equalsIgnoreCase(string))
			{
				return cmd;
			}
		}
		throw new IllegalArgumentException("Command " + string + " not found");
	}

	public static String description()
	{
		String ret = "Commands supported by the client:\n";
		for (Command cmd : Command.values())
		{	 
			ret += "\t" + cmd.name() + "\n";
		}
		ret += "use help,<CommandName> for more detailed information";
		return ret;
	}

	public String toString()
	{
		String ret = name() + ": " + m_description + "\n";
		ret += "Usage: " + name() + "," + m_args;
		return ret;
	}
}

package Client;

import Server.Interface.*;

import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;
import java.rmi.RemoteException;
import java.rmi.NotBoundException;

import java.util.*;
import java.io.*;

public class RMIClient extends Client
{
	private static String s_serverHost = "localhost";
        // recommended to hange port last digits to your group number
	private static int s_serverPort = 3042;
	private static String s_serverName = "Resources";

	//TODO: ADD YOUR GROUP NUMBER TO COMPILE
	private static String s_rmiPrefix = "group_42_";

	public static void main(String args[])
	{	
		if (args.length > 0)
		{
			s_serverHost = args[0];
		}
		if (args.length > 1)
		{
			s_serverName = args[1];
		}
		if (args.length > 2)
		{
			System.err.println((char)27 + "[31;1mClient exception: " + (char)27 + "[0mUsage: java client.RMIClient [server_hostname [server_rmiobject]]");
			System.exit(1);
		}

		// Get a reference to the RMIRegister
		try {
			RMIClient client = new RMIClient();
			client.connectServer();
			client.start();
		} 
		catch (Exception e) {    
			System.err.println((char)27 + "[31;1mClient exception: " + (char)27 + "[0mUncaught exception");
			e.printStackTrace();
			System.exit(1);
		}
	}

	public RMIClient()
	{
		super();
	}

	public void connectServer()
	{
		connectServer(s_serverHost, s_serverPort, s_serverName);
	}

	public void connectServer(String server, int port, String name)
	{
		try {
			boolean first = true;
			while (true) {
				try {
					Registry registry = LocateRegistry.getRegistry(server, port);
					m_resourceManager = (IResourceManager)registry.lookup(s_rmiPrefix + name);
					System.out.println("Connected to '" + name + "' server [" + server + ":" + port + "/" + s_rmiPrefix + name + "]");
					break;
				}
				catch (NotBoundException|RemoteException e) {
					if (first) {
						System.out.println("Waiting for '" + name + "' server [" + server + ":" + port + "/" + s_rmiPrefix + name + "]");
						first = false;
					}
				}
				Thread.sleep(500);
			}
		}
		catch (Exception e) {
			System.err.println((char)27 + "[31;1mServer exception: " + (char)27 + "[0mUncaught exception");
			e.printStackTrace();
			System.exit(1);
		}
	}
}

package Server.Interface;

import java.rmi.Remote;
import java.rmi.RemoteException;

import java.util.*;

/** 
 * Simplified version from CSE 593 Univ. of Washington
 *
 * Distributed  System in Java.
 * 
 * failure reporting is done using two pieces, exceptions and boolean 
 * return values.  Exceptions are used for systemy things. Return
 * values are used for operations that would affect the consistency
 * 
 * If there is a boolean return value and you're not sure how it 
 * would be used in your implementation, ignore it.  I used boolean
 * return values in the interface generously to allow flexibility in 
 * implementation.  But don't forget to return true when the operation
 * has succeeded.
 */

public interface IResourceManager extends Remote 
{
    /**
     * Add seats to a flight.
     *
     * In general this will be used to create a new
     * flight, but it should be possible to add seats to an existing flight.
     * Adding to an existing flight should overwrite the current price of the
     * available seats.
     *
     * @return Success
     */
    public boolean addFlight(int flightNum, int flightSeats, int flightPrice) 
	throws RemoteException; 

    /**
     * Add car at a location.
     *
     * This should look a lot like addFlight, only keyed on a string location
     * instead of a flight number.
     *
     * @return Success
     */
    public boolean addCars(String location, int numCars, int price) 
	throws RemoteException; 

    /**
     * Add room at a location.
     *
     * This should look a lot like addFlight, only keyed on a string location
     * instead of a flight number.
     *
     * @return Success
     */
    public boolean addRooms(String location, int numRooms, int price) 
	throws RemoteException; 			    

    /**
     * Add customer.
     *
     * @return Unique customer identifier
     */
    public int newCustomer() 
	throws RemoteException; 

    /**
     * Add customer with id.
     *
     * @return Success
     */
    public boolean newCustomer(int cid)
        throws RemoteException;

    /**
     * Delete the flight.
     *
     * deleteFlight implies whole deletion of the flight. If there is a
     * reservation on the flight, then the flight cannot be deleted
     *
     * @return Success
     */   
    public boolean deleteFlight(int flightNum) 
	throws RemoteException; 

    /**
     * Delete all cars at a location.
     *
     * It may not succeed if there are reservations for this location
     *
     * @return Success
     */		    
    public boolean deleteCars(String location) 
	throws RemoteException; 

    /**
     * Delete all rooms at a location.
     *
     * It may not succeed if there are reservations for this location.
     *
     * @return Success
     */
    public boolean deleteRooms(String location) 
	throws RemoteException; 

    /**
     * Delete a customer and associated reservations.
     *
     * @return Success
     */
    public boolean deleteCustomer(int customerID) 
	throws RemoteException; 

    /**
     * Query the status of a flight.
     *
     * @return Number of empty seats
     */
    public int queryFlight(int flightNumber) 
	throws RemoteException; 

    /**
     * Query the status of a car location.
     *
     * @return Number of available cars at this location
     */
    public int queryCars(String location) 
	throws RemoteException; 

    /**
     * Query the status of a room location.
     *
     * @return Number of available rooms at this location
     */
    public int queryRooms(String location) 
	throws RemoteException; 

    /**
     * Query the customer reservations.
     *
     * @return A formatted bill for the customer
     */
    public String queryCustomerInfo(int customerID) 
	throws RemoteException; 

    /**
     * Query the status of a flight.
     *
     * @return Price of a seat in this flight
     */
    public int queryFlightPrice(int flightNumber) 
	throws RemoteException; 

    /**
     * Query the status of a car location.
     *
     * @return Price of car
     */
    public int queryCarsPrice(String location) 
	throws RemoteException; 

    /**
     * Query the status of a room location.
     *
     * @return Price of a room
     */
    public int queryRoomsPrice(String location) 
	throws RemoteException; 

    /**
     * Reserve a seat on this flight.
     *
     * @return Success
     */
    public boolean reserveFlight(int customerID, int flightNumber) 
	throws RemoteException; 

    /**
     * Reserve a car at this location.
     *
     * @return Success
     */
    public boolean reserveCar(int customerID, String location) 
	throws RemoteException; 

    /**
     * Reserve a room at this location.
     *
     * @return Success
     */
    public boolean reserveRoom(int customerID, String location) 
	throws RemoteException; 

    /**
     * Reserve a bundle for the trip.
     *
     * @return Success
     */
    public boolean bundle(int customerID, Vector<String> flightNumbers, String location, boolean car, boolean room)
	throws RemoteException; 

    /**
     * Convenience for probing the resource manager.
     *
     * @return Name
     */
    public String getName()
        throws RemoteException;
}

package Client;

import Server.Interface.*;

import java.util.*;
import java.io.*;
import java.rmi.RemoteException;
import java.rmi.ConnectException;
import java.rmi.ServerException;
import java.rmi.UnmarshalException;

public abstract class Client
{
	IResourceManager m_resourceManager = null;

	public Client()
	{
		super();
	}

	public abstract void connectServer();

	public void start()
	{
		// Prepare for reading commands
		System.out.println();
		System.out.println("Location \"help\" for list of supported commands");

		BufferedReader stdin = new BufferedReader(new InputStreamReader(System.in));

		while (true)
		{
			// Read the next command
			String command = "";
			Vector<String> arguments = new Vector<String>();
			try {
				System.out.print((char)27 + "[32;1m\n>] " + (char)27 + "[0m");
				command = stdin.readLine().trim();
			}
			catch (IOException io) {
				System.err.println((char)27 + "[31;1mClient exception: " + (char)27 + "[0m" + io.getLocalizedMessage());
				io.printStackTrace();
				System.exit(1);
			}

			try {
				arguments = parse(command);
				Command cmd = Command.fromString((String)arguments.elementAt(0));
				try {
					execute(cmd, arguments);
				}
				catch (ConnectException e) {
					connectServer();
					execute(cmd, arguments);
				}
			}
			catch (IllegalArgumentException|ServerException e) {
				System.err.println((char)27 + "[31;1mCommand exception: " + (char)27 + "[0m" + e.getLocalizedMessage());
			}
			catch (ConnectException|UnmarshalException e) {
				System.err.println((char)27 + "[31;1mCommand exception: " + (char)27 + "[0mConnection to server lost");
			}
			catch (Exception e) {
				System.err.println((char)27 + "[31;1mCommand exception: " + (char)27 + "[0mUncaught exception");
				e.printStackTrace();
			}
		}
	}

	public void execute(Command cmd, Vector<String> arguments) throws RemoteException, NumberFormatException
	{
		switch (cmd)
		{
			case Help:
			{
				if (arguments.size() == 1) {
					System.out.println(Command.description());
				} else if (arguments.size() == 2) {
					Command l_cmd = Command.fromString((String)arguments.elementAt(1));
					System.out.println(l_cmd.toString());
				} else {
					System.err.println((char)27 + "[31;1mCommand exception: " + (char)27 + "[0mImproper use of help command. Location \"help\" or \"help,<CommandName>\"");
				}
				break;
			}
			case AddFlight: {
				checkArgumentsCount(4, arguments.size());

				System.out.println("Adding a new flight ");
				System.out.println("-Flight Number: " + arguments.elementAt(1));
				System.out.println("-Flight Seats: " + arguments.elementAt(2));
				System.out.println("-Flight Price: " + arguments.elementAt(3));

				int flightNum = toInt(arguments.elementAt(1));
				int flightSeats = toInt(arguments.elementAt(2));
				int flightPrice = toInt(arguments.elementAt(3));

				if (m_resourceManager.addFlight(flightNum, flightSeats, flightPrice)) {
					System.out.println("Flight added");
				} else {
					System.out.println("Flight could not be added");
				}
				break;
			}
			case AddCars: {
				checkArgumentsCount(4, arguments.size());

				System.out.println("Adding new cars");
				System.out.println("-Car Location: " + arguments.elementAt(1));
				System.out.println("-Number of Cars: " + arguments.elementAt(2));
				System.out.println("-Car Price: " + arguments.elementAt(3));

				String location = arguments.elementAt(1);
				int numCars = toInt(arguments.elementAt(2));
				int price = toInt(arguments.elementAt(3));

				if (m_resourceManager.addCars(location, numCars, price)) {
					System.out.println("Cars added");
				} else {
					System.out.println("Cars could not be added");
				}
				break;
			}
			case AddRooms: {
				checkArgumentsCount(4, arguments.size());

				System.out.println("Adding new rooms");
				System.out.println("-Room Location: " + arguments.elementAt(1));
				System.out.println("-Number of Rooms: " + arguments.elementAt(2));
				System.out.println("-Room Price: " + arguments.elementAt(3));

	       			String location = arguments.elementAt(1);
				int numRooms = toInt(arguments.elementAt(2));
				int price = toInt(arguments.elementAt(3));

				if (m_resourceManager.addRooms(location, numRooms, price)) {
					System.out.println("Rooms added");
				} else {
					System.out.println("Rooms could not be added");
				}
				break;
			}
			case AddCustomer: {
				checkArgumentsCount(1, arguments.size());

				System.out.println("Adding a new customer:=");

				int customer = m_resourceManager.newCustomer();

				System.out.println("Add customer ID: " + customer);
				break;
			}
			case AddCustomerID: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Adding a new customer");
				System.out.println("-Customer ID: " + arguments.elementAt(1));

				int customerID = toInt(arguments.elementAt(1));

				if (m_resourceManager.newCustomer(customerID)) {
					System.out.println("Add customer ID: " + customerID);
				} else {
					System.out.println("Customer could not be added");
				}
				break;
			}
			case DeleteFlight: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Deleting a flight");
				System.out.println("-Flight Number: " + arguments.elementAt(1));

				int flightNum = toInt(arguments.elementAt(1));

				if (m_resourceManager.deleteFlight(flightNum)) {
					System.out.println("Flight Deleted");
				} else {
					System.out.println("Flight could not be deleted");
				}
				break;
			}
			case DeleteCars: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Deleting all cars at a particular location");
				System.out.println("-Car Location: " + arguments.elementAt(1));

				String location = arguments.elementAt(1);

				if (m_resourceManager.deleteCars(location)) {
					System.out.println("Cars Deleted");
				} else {
					System.out.println("Cars could not be deleted");
				}
				break;
			}
			case DeleteRooms: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Deleting all rooms at a particular location");
				System.out.println("-Car Location: " + arguments.elementAt(1));

				String location = arguments.elementAt(1);

				if (m_resourceManager.deleteRooms(location)) {
					System.out.println("Rooms Deleted");
				} else {
					System.out.println("Rooms could not be deleted");
				}
				break;
			}
			case DeleteCustomer: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Deleting a customer from the database");
				System.out.println("-Customer ID: " + arguments.elementAt(1));
				
				int customerID = toInt(arguments.elementAt(1));

				if (m_resourceManager.deleteCustomer(customerID)) {
					System.out.println("Customer Deleted");
				} else {
					System.out.println("Customer could not be deleted");
				}
				break;
			}
			case QueryFlight: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Querying a flight");
				System.out.println("-Flight Number: " + arguments.elementAt(1));
				
				int flightNum = toInt(arguments.elementAt(1));

				int seats = m_resourceManager.queryFlight(flightNum);
				System.out.println("Number of seats available: " + seats);
				break;
			}
			case QueryCars: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Querying cars location");
				System.out.println("-Car Location: " + arguments.elementAt(1));
				
				String location = arguments.elementAt(1);

				int numCars = m_resourceManager.queryCars(location);
				System.out.println("Number of cars at this location: " + numCars);
				break;
			}
			case QueryRooms: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Querying rooms location");
				System.out.println("-Room Location: " + arguments.elementAt(1));
				
			
				String location = arguments.elementAt(1);

				int numRoom = m_resourceManager.queryRooms(location);
				System.out.println("Number of rooms at this location: " + numRoom);
				break;
			}
			case QueryCustomer: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Querying customer information");
				System.out.println("-Customer ID: " + arguments.elementAt(1));

				int customerID = toInt(arguments.elementAt(1));

				String bill = m_resourceManager.queryCustomerInfo(customerID);
				System.out.print(bill);
				break;               
			}
			case QueryFlightPrice: {
				checkArgumentsCount(2, arguments.size());
				
				System.out.println("Querying a flight price");
				System.out.println("-Flight Number: " + arguments.elementAt(1));

				int flightNum = toInt(arguments.elementAt(1));

				int price = m_resourceManager.queryFlightPrice(flightNum);
				System.out.println("Price of a seat: " + price);
				break;
			}
			case QueryCarsPrice: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Querying cars price");
				System.out.println("-Car Location: " + arguments.elementAt(1));

				String location = arguments.elementAt(1);

				int price = m_resourceManager.queryCarsPrice(location);
				System.out.println("Price of cars at this location: " + price);
				break;
			}
			case QueryRoomsPrice: {
				checkArgumentsCount(2, arguments.size());

				System.out.println("Querying rooms price");
				System.out.println("-Room Location: " + arguments.elementAt(1));

				String location = arguments.elementAt(1);

				int price = m_resourceManager.queryRoomsPrice(location);
				System.out.println("Price of rooms at this location: " + price);
				break;
			}
			case ReserveFlight: {
				checkArgumentsCount(3, arguments.size());

				System.out.println("Reserving seat in a flight");
				System.out.println("-Customer ID: " + arguments.elementAt(1));
				System.out.println("-Flight Number: " + arguments.elementAt(2));

				int customerID = toInt(arguments.elementAt(1));
				int flightNum = toInt(arguments.elementAt(2));

				if (m_resourceManager.reserveFlight(customerID, flightNum)) {
					System.out.println("Flight Reserved");
				} else {
					System.out.println("Flight could not be reserved");
				}
				break;
			}
			case ReserveCar: {
				checkArgumentsCount(3, arguments.size());

				System.out.println("Reserving a car at a location");
				System.out.println("-Customer ID: " + arguments.elementAt(1));
				System.out.println("-Car Location: " + arguments.elementAt(2));

				int customerID = toInt(arguments.elementAt(1));
				String location = arguments.elementAt(2);

				if (m_resourceManager.reserveCar(customerID, location)) {
					System.out.println("Car Reserved");
				} else {
					System.out.println("Car could not be reserved");
				}
				break;
			}
			case ReserveRoom: {
				checkArgumentsCount(3, arguments.size());

				System.out.println("Reserving a room at a location");
				System.out.println("-Customer ID: " + arguments.elementAt(1));
				System.out.println("-Room Location: " + arguments.elementAt(2));
				
				int customerID = toInt(arguments.elementAt(1));
				String location = arguments.elementAt(2);

				if (m_resourceManager.reserveRoom(customerID, location)) {
					System.out.println("Room Reserved");
				} else {
					System.out.println("Room could not be reserved");
				}
				break;
			}
			case Bundle: {
				if (arguments.size() < 6) {
					System.err.println((char)27 + "[31;1mCommand exception: " + (char)27 + "[0mBundle command expects at least 6 arguments. Location \"help\" or \"help,<CommandName>\"");
					break;
				}

				System.out.println("Reserving an bundle");
				System.out.println("-Customer ID: " + arguments.elementAt(1));
				for (int i = 0; i < arguments.size() - 5; ++i)
				{
					System.out.println("-Flight Number: " + arguments.elementAt(2+i));
				}
				System.out.println("-Location for Car/Room: " + arguments.elementAt(arguments.size()-3));
				System.out.println("-Book Car: " + arguments.elementAt(arguments.size()-2));
				System.out.println("-Book Room: " + arguments.elementAt(arguments.size()-1));

				int customerID = toInt(arguments.elementAt(1));
				Vector<String> flightNumbers = new Vector<String>();
				for (int i = 0; i < arguments.size() - 5; ++i)
				{
					flightNumbers.addElement(arguments.elementAt(2+i));
				}
				String location = arguments.elementAt(arguments.size()-3);
				boolean car = toBoolean(arguments.elementAt(arguments.size()-2));
				boolean room = toBoolean(arguments.elementAt(arguments.size()-1));
				if (m_resourceManager.bundle(customerID, flightNumbers, location, car, room)) {
					System.out.println("Bundle Reserved");
				} else {
					System.out.println("Bundle could not be reserved");
				}
				break;
			}
			case Quit:
				checkArgumentsCount(1, arguments.size());

				System.out.println("Quitting client");
				System.exit(0);
		}
	}

	public static Vector<String> parse(String command)
	{
		Vector<String> arguments = new Vector<String>();
		StringTokenizer tokenizer = new StringTokenizer(command,",");
		String argument = "";
		while (tokenizer.hasMoreTokens())
		{
			argument = tokenizer.nextToken();
			argument = argument.trim();
			arguments.add(argument);
		}
		return arguments;
	}

	public static void checkArgumentsCount(Integer expected, Integer actual) throws IllegalArgumentException
	{
		if (expected != actual)
		{
			throw new IllegalArgumentException("Invalid number of arguments. Expected " + (expected - 1) + ", received " + (actual - 1) + ". Location \"help,<CommandName>\" to check usage of this command");
		}
	}

	public static int toInt(String string) throws NumberFormatException
	{
		return (Integer.valueOf(string)).intValue();
	}

	public static boolean toBoolean(String string)// throws Exception
	{
		return (Boolean.valueOf(string)).booleanValue();
	}
}

package Server.RMI;

import Server.Interface.*;
import Server.Common.Trace;
import Server.Common.Customer;
import java.util.*;
import java.rmi.RemoteException;
import java.io.*;
import Server.RMI.ResItemEnum;
import java.rmi.registry.Registry;
import java.rmi.registry.LocateRegistry;
import java.rmi.AlreadyBoundException;
import java.rmi.server.UnicastRemoteObject;
import java.rmi.NotBoundException;
public class Middleware implements IResourceManager{
	HashMap<ResItemEnum, List<IResourceManager>> managers = new HashMap<ResItemEnum, List<IResourceManager>>();	
	//To distribute relatively equally, we naively traverse the list of counters with each operation. Delete operations, which access RM's randomly, will break LRU
	HashMap<ResItemEnum, Integer> lruRM = new HashMap<ResItemEnum,Integer>();
	static int port = 3042;
	static String prefix = "group_42_";
	static String name = "Middleware";
	int cusID = 0;
	public Middleware() {
		//initializes counters to -1, since update occurs before each use.
		//This should be safe, no access will occur at this point.
		for(ResItemEnum x : ResItemEnum.values()) {
			managers.put(x, new ArrayList<IResourceManager>());
			lruRM.put(x, -1);
		}	

	}	

	public boolean addFlight(int flightNum, int flightSeats, int flightPrice) throws RemoteException {
		if (readManager(ResItemEnum.FLIGHT).isEmpty()) {
			Trace.warn("No flight manager available");
			return false;
		}
		synchronized (lruRM) {
			updateLRURM(ResItemEnum.FLIGHT);
			return readManager(ResItemEnum.FLIGHT).get(readLRURM(ResItemEnum.FLIGHT)).addFlight(flightNum, flightSeats, flightPrice);
		}

	}

	public boolean addCars(String location, int numCars, int price) throws RemoteException {
		if (readManager(ResItemEnum.CAR).isEmpty()) {
			Trace.warn("No car manager available");
			return false;
		}
		synchronized (lruRM) {
			updateLRURM(ResItemEnum.CAR);
			return readManager(ResItemEnum.CAR).get(readLRURM(ResItemEnum.CAR)).addCars(location, numCars, price);
		}


	}

	public boolean addRooms(String location, int numRooms, int price) throws RemoteException {
		if (managers.get(ResItemEnum.ROOM).isEmpty()) {
			Trace.warn("No room manager available");
			return false;
		}
		synchronized (lruRM) {
			updateLRURM(ResItemEnum.ROOM);
			return readManager(ResItemEnum.ROOM).get(readLRURM(ResItemEnum.ROOM)).addRooms(location, numRooms, price);
		}	

	}

	public int newCustomer() throws RemoteException {
		//TODO: Figure out how to handle what to do if one of them throws an error. It might be fine through redundacy? If the customer is never added then it just has no clue for any other related call? But if a flight is added to it it might delete it accidentally?
		for(ResItemEnum x : ResItemEnum.values()) {
			for(IResourceManager i : readManager(x)) {
				//since all RM's have the same customers, this should only have to loop for the first object, ensuring that every RM has the same cid.
				while(!i.newCustomer(cusID)) {
					++cusID;
				}
			}
		}
		return cusID++;
	}

	public boolean newCustomer(int cid) throws RemoteException {
		boolean status = true;
		for(ResItemEnum x : ResItemEnum.values()) {
			for(IResourceManager i : readManager(x)) {
				status = i.newCustomer(cid) && status; 
			}
		}
		return status;
	}

	public boolean deleteFlight(int flightNum) throws RemoteException {
		boolean status = true;
		for (IResourceManager x : readManager(ResItemEnum.FLIGHT)) {
			status = status && x.deleteFlight(flightNum);
		}
		return status;
	}

	public boolean deleteCars(String location) throws RemoteException {
		boolean status = true;
		for (IResourceManager x : readManager(ResItemEnum.CAR)) {
			status =  x.deleteCars(location) || status;
		}
		return status;
	}

	public boolean deleteRooms(String location) throws RemoteException {
		boolean status = true;
		for (IResourceManager x : readManager(ResItemEnum.ROOM)) {
			status =  x.deleteRooms(location) || status;
		}
		return status;
	}

	public boolean deleteCustomer(int customerID) throws RemoteException {
		boolean status = true;
		for(ResItemEnum x : ResItemEnum.values()) {
			for(IResourceManager i : readManager(x)) {
				status = i.deleteCustomer(customerID) && status;
			}
		}
		return status;
	}

	public int queryFlight(int flightNumber) throws RemoteException {
		for(IResourceManager x : readManager(ResItemEnum.FLIGHT)) {
			if (x.queryFlight(flightNumber) > 0) {
				return x.queryFlight(flightNumber);
			}
		}
		return 0;
	}

	public int queryCars(String location) throws RemoteException {
		for(IResourceManager x : readManager(ResItemEnum.CAR)) {
			if (x.queryCars(location) > 0) {
				return x.queryCars(location);
			}
		}
		return 0;
	}

	public int queryRooms(String location) throws RemoteException {
