	private void closeAfterFailure()
	{
		try
		{
			if (channel != null)
			{
				channel.close();
			}
		}
		catch (IOException ignored)
		{
			// The original request failure is reported to the caller.
		}
		finally
		{
			channel = null;
		}
	}

